<body>

    <h1>Falling Sand Simulator</h1>

    <div id="container">
        <!-- Canvas element for rendering -->
        <canvas id="sand"></canvas>

        <!-- Controls Panel -->
        <div id="controls">
            <h2>Materials</h2>
            <div class="button-group">
