                <button class="material-btn" id="mat-water">Water (&diams;) </button>
                <button class="material-btn" id="mat-wall">Wall (█)</button>
                <button class="material-btn" id="mat-acid">Acid (~A~)</button>
            </div>

            <!-- Eraser/Empty Material -->
             <button class="material-btn" id="mat-empty">Eraser (Empty)</button>

            <button id="clear">Clear Grid</button>

            <div style="margin-top: 20px;">
                <strong>Status:</strong> <span id="current-material">Sand</span>
            </div>
        </div>
    </div>


<script>
// ==============================================
// GLOBAL SIMULATION SETUP
// ==============================================

const CANVAS_SIZE = 450; // Target CSS pixels size
const GRID_W = 100;     // Grid width in cells (must be >= 80)
const GRID_H = 100;     // Grid height in cells (must be >= 80)

const MATERIALS = {
    EMPTY: "empty",
    SAND: "sand",
    WATER: "water",
    WALL: "wall",
    ACID: "acid"
};

let currentMaterial = MATERIALS.SAND;
let isPainting = false;

// DOM Elements
const canvas = document.getElementById('sand');
const ctx = canvas.getContext('2d');
const materialButtons = {
    'mat-sand': MATERIALS.SAND,
    'mat-water': MATERIALS.WATER,
    'mat-wall': MATERIALS.WALL,
    'mat-acid': MATERIALS.ACID,
    'mat-empty': MATERIALS.EMPTY
};

// Set canvas size CSS and actual drawing buffer resolution (pixel mapping)
canvas.width = CANVAS_SIZE; 
canvas.height = CANVAS_SIZE;


/**
 * Core Simulation State Object
 * Implements the required programmatic API: window.sim
 */
const simState = {
    grid: [], // 2D array holding materials

    initializeGrid() {
        this.grid = [];
        for (let y = 0; y < GRID_H; y++) {
            this.grid[y] = new Array(GRID_W).fill(MATERIALS.EMPTY);
        }
    },

    // API: Get material at (x, y)
    get(x, y) {
        if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) {
            return null; // Out of bounds indicator
        }
        return this.grid[y][x];
    },

    // API: Set material at (x, y)
    set(x, y, material) {
        if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return false;
        this.grid[y][x] = material;
        return true;
    },

    // API: Clear the whole grid
    clear() {
        for (let y = 0; y < GRID_H; y++) {
            for (let x = 0; x < GRID_W; x++) {
                this.set(x, y, MATERIALS.EMPTY);
            }
        }
        drawGrid(); // Redraw immediately upon clear
    },

    // API: Advance the simulation by n steps synchronously
    tick(n) {
        for (let step = 0; step < n; step++) {
            this.stepSimulation();
        }
    },

    // Internal function to run one full physics step
    stepSimulation() {
        const currentGrid = this.grid;
        // We MUST calculate the next state based entirely on the *current* grid state, 
        // so we use a deep copy or create an entirely new grid for the results.
        let nextGrid = [];
        for (let y = 0; y < GRID_H; y++) {
            nextGrid[y] = [...currentGrid[y]];
        }

        // Iterate bottom-up to ensure particles only move one step down/side per tick,
        // and that lower cells are processed before higher ones.
        for (let y = GRID_H - 2; y >= 0; y--) {
            for (let x = 0; x < GRID_W; x++) {
                const material = currentGrid[y][x];
                if (material === MATERIALS.EMPTY || material === MATERIALS.WALL) continue;

                // The physics functions modify `nextGrid` in place, moving content from `currentGrid`.
                this.processParticle(x, y, material, nextGrid);
            }
        }

        this.grid = nextGrid;
    },

    /**
     * Processes the particle at (x, y) based on its current material rules.
     * Modifies `nextGrid` to determine where the material *will be* in the next step.
     */
    processParticle(x, y, material, nextGrid) {
        // 1. Check for Acid Dissolution (Always affects neighbors/below first)
        if (material === MATERIALS.ACID) {
            const currentCell = this.getNeighborMaterial(x, y); // Should be the input particle
            let new_x = x;
            let new_y = y;

            // --- Dissolution Check: Down and Sides ---
            // We check neighbors in the *current* grid (before movement) for targets
            const potentialDissolves = [];

            // Check below
            if (y + 1 < GRID_H && this.get(x, y + 1) === MATERIALS.SAND || this.get(x, y + 1) === MATERIALS.WALL) {
                potentialDissolves.push({ dx: 0, dy: 1 });
            }
             // Check sides (y is same level)
            if (x - 1 >= 0 && this.get(x - 1, y) === MATERIALS.SAND || this.get(x - 1, y) === MATERIALS.WALL) {
                potentialDissolves.push({ dx: -1, dy: 0 });
            }
            if (x + 1 < GRID_W && this.get(x + 1, y) === MATERIALS.SAND || this.get(x + 1, y) === MATERIALS.WALL) {
                potentialDissolves.push({ dx: 1, dy: 0 });
            }

            for (const d of potentialDissolves) {
                 // If dissolution occurs, the target cell becomes empty in the *next* step grid
                if (d.dy === 1 && y + 1 < GRID_H) { // Only dissolving below is guaranteed to happen if space allows
                    if (this.get(x, y+1) === MATERIALS.SAND || this.get(x, y+1) === MATERIALS.WALL) {
                         nextGrid[y+1][x] = MATERIALS.EMPTY;
                    }
                } else if (d.dy === 0 && d.dx !== 0) { // Dissolving sideways at the same level is complex for CA.
                     // For simplicity and stability, we only guarantee vertical dissolution below.
                     // The particle itself moves/flows, dissolving what it lands near or on.
                }
            }

            // Acid movement logic (same as water)
            this.processLiquid(x, y, nextGrid);


        } 

        // 2. Water Movement
        else if (material === MATERIALS.WATER) {
            this.processLiquid(x, y, nextGrid);
        }

        // 3. Sand Movement
        else if (material === MATERIALS.SAND) {
             let next_x = x;
             let next_y = y + 1; // Target location for fall

             // Try direct drop first
             if (next_y < GRID_H && currentGrid[next_y][x] === MATERIALS.EMPTY) {
                 // Simple fall
                 nextGrid[next_y][next_x] = MATERIALS.SAND;
                 return; 
             }

             // If blocked, try diagonal slide (randomize direction check order)
             const directions = [
                { dx: -1, dy: 1 }, // Down-Left
                { dx: 1, dy: 1 }   // Down-Right
            ];
            directions.sort(() => Math.random() - 0.5); // Randomize order

            for (const dir of directions) {
                let test_x = x + dir.dx;
                let test_y = y + dir.dy;

                if (test_x >= 0 && test_x < GRID_W && test_y >= 0 && test_y < GRID_H && currentGrid[test_y][test_x] === MATERIALS.EMPTY) {
                     // Slide found!
                    nextGrid[test_y][test_x] = MATERIALS.SAND;
                    return;
                }
            }

             // If all else fails, it rests (already copied into nextGrid implicitly unless moved)
        }

        // 4. Liquids/Particles that did not move or were blocked remain in place
        if (nextGrid[y][x] === MATERIALS.EMPTY && material !== MATERIALS.EMPTY) {
             nextGrid[y][x] = material;
        }

    }
};


/**
 * Handles generic fluid movement logic for Water and Acid.
 * Attempts to move down, then spreads sideways/diagonally if blocked.
 */
simState.processLiquid = function(x, y, nextGrid) {
    // 1. Attempt Vertical Fall (Down)
    const next_y = y + 1;
    if (next_y < GRID_H && simState.get(x, next_y) === MATERIALS.EMPTY) {
        // Success: Move down and place particle in the new spot
        nextGrid[next_y][x] = this.grid[y][x]; 
        return;
    }

    // 2. Attempt Horizontal Spread (Left/Right) if blocked below OR already settled
    if (this.grid[y][x] === MATERIALS.WATER || this.grid[y][x] === MATERIALS.ACID) {
        const neighbors = [];

        // Check Left and Right first
        if (x - 1 >= 0 && this.get(x - 1, y) === MATERIALS.EMPTY) neighbors.push({ dx: -1, dy: 0 });
        if (x + 1 < GRID_W && this.get(x + 1, y) === MATERIALS.EMPTY) neighbors.push({ dx: 1, dy: 0 });

        // If horizontal spread fails, check diagonal/down-side fallback (simplified to just prioritize side flow if stuck)
        if (neighbors.length > 0) {
            // Randomize direction preference for spreading
            neighbors.sort(() => Math.random() - 0.5);

            for (const d of neighbors) {
                nextGrid[y + d.dy][x + d.dx] = this.grid[y][x];
                return;
            }
        }

        // If stuck completely, it remains in the same spot unless dissolved by acid
        // (The initial copy handles remaining particles)
    }
};


/** Helper to get material from current state for Acid/Water checks */
simState.getNeighborMaterial = function(x, y) {
     if (x < 0 || x >= GRID_W || y < 0 || y >= GRID_H) return null;
     return simState.grid[y][x];
}


// ==============================================
// VISUALIZATION AND INPUT HANDLING
// ==============================================

/** Converts grid coordinates (x, y) to canvas pixel coordinates */
function getPixelCoords(x, y) {
    const size = CANVAS_SIZE / GRID_W; // Assuming square cells for simplicity: 450/100 = 4.5px per cell?
    // Let's use a fixed scaling factor based on the number of pixels and grid dimensions
    const scaleX = canvas.width / GRID_W;
    const scaleY = canvas.height / GRID_H;

    return {
        x: x * scaleX,
        y: y * scaleY
    };
}


/** Renders the current state of the simulation grid onto the canvas */
function drawGrid() {
    ctx.clearRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

    // Helper function to get color/symbol based on material (CSS mapping)
    const getColor = (material) => {
        switch (material) {
            case MATERIALS.EMPTY: return '#121212'; // Dark background
            case MATERIALS.SAND: return '#ffc107'; 
            case MATERIALS.WATER: return '#2196f3'; 
            case MATERIALS.WALL: return '#455a64'; 
            case MATERIALS.ACID: return '#ff5722'; 
            default: return '#000';
        }
    };

    // Cell dimensions in pixels
    const pixelWidth = CANVAS_SIZE / GRID_W;
    const pixelHeight = CANVAS_SIZE / GRID_H;


    for (let y = 0; y < GRID_H; y++) {
        for (let x = 0; x < GRID_W; x++) {
            const material = simState.get(x, y);
            if (material !== MATERIALS.EMPTY) {
                ctx.fillStyle = getColor(material);
                ctx.fillRect(x * pixelWidth, y * pixelHeight, pixelWidth - 0.5, pixelHeight - 0.5);
            } else {
                 // Draw background slightly darker to emphasize cell boundaries if empty
                ctx.fillStyle = '#0a0a0a';
                ctx.fillRect(x * pixelWidth, y * pixelHeight, pixelWidth - 0.5, pixelHeight - 0.5);
            }
        }
    }
}

/** Handles mouse clicks/drags to paint materials on the grid */
function handlePainting(event) {
    let rect = canvas.getBoundingClientRect();
    const clientX = event.clientX || event.touches[0].clientX;
    const clientY = event.clientY || event.touches[0].clientY;

    // Calculate position relative to the canvas element
    const scaleX = CANVAS_SIZE / rect.width;
    const scaleY = CANVAS_SIZE / rect.height;

    let xPixel = (clientX - rect.left) * scaleX;
    let yPixel = (clientY - rect.top) * scaleY;

    // Convert pixel coordinates to grid cell indices (x, y)
    const x = Math.floor(xPixel / (CANVAS_SIZE / GRID_W));
    const y = Math.floor(yPixel / (CANVAS_SIZE / GRID_H));

    if (x >= 0 && x < GRID_W && y >= 0 && y < GRID_H) {
        simState.set(Math.floor(x), Math.floor(y), currentMaterial);
        drawGrid(); // Immediate redraw on paint action
    }
}

// Event Listeners for Painting
canvas.addEventListener('mousedown', (e) => {
    isPainting = true;
    handlePainting(e);
});
document.addEventListener('mouseup', () => {
    isPainting = false;
});
canvas.addEventListener('mousemove', (e) => {
    if (isPainting) handlePainting(e);
});

// Touch support for mobile/tablet
canvas.addEventListener('touchstart', (e) => {
    e.preventDefault(); // Prevent scrolling when touching canvas
    isPainting = true;
    handlePainting(e);
}, { passive: false });

canvas.addEventListener('touchend', () => {
    isPainting = false;
});
canvas.addEventListener('touchmove', (e) => {
    if (isPainting) handlePainting(e);
}, { passive: false });


/** Initializes UI controls and event handlers */
function setupControls() {
    const clearBtn = document.getElementById('clear');
    clearBtn.onclick = () => {
        simState.clear();
    };

    // Material Selector Buttons Setup
    Object.keys(materialButtons).forEach(id => {
        const button = document.getElementById(id);
        if (button) {
            button.addEventListener('click', () => {
                currentMaterial = materialButtons[id];
                document.getElementById('current-material').textContent = currentMaterial.charAt(0).toUpperCase() + currentMaterial.slice(1);
            });
        }
    });

     // Initial state display update
    document.getElementById('current-material').textContent = 'Sand';


    // Setup periodic simulation loop (Animation/Tick)
    const animate = () => {
        // Run 1 step every frame for continuous animation
        simState.stepSimulation(); 
        drawGrid();
        requestAnimationFrame(animate);
    };

    // Start the visual animation loop
    animate();


    // Expose API (This runs once and keeps the simulation running visually)
    window.sim = {
        w: GRID_W, 
        h: GRID_H, 
        tick: function(n) {
            console.log(`[API] Running synchronous tick for ${n} steps.`);
            this.stepSimulation(); // The internal stepSimulation is what runs the physics logic
            for (let i = 1; i < n; i++) {
                this.stepSimulation();
            }
        },
        get: simState.get,
        set: simState.set,
        clear: () => {
            simState.clear();
            // Note: The internal animation loop will continue rendering the cleared state.
        },
    };
}

window.onload = setupControls;

</script>
</body>
</html>
